from pydantic import BaseModel, Field
from typing import Dict, Any, Optional, List

class PlatformInvocationRequest(BaseModel):
    text: str
    temperature: Optional[float] = Field(default=0.7, ge=0.0, le=2.0)
    max_tokens: Optional[int] = Field(default=500, ge=1)

class PlatformInvocationResponse(BaseModel):
    text: str
    metadata: Optional[Dict[str, Any]] = None

class StreamingPlatformInvocationResponse(BaseModel):
    chunk: str
    metadata: Optional[Dict[str, Any]] = None

class PlatformSafetyCheckRequest(BaseModel):
    text: str

class PlatformSafetyCheckResponse(BaseModel):
    is_safe: bool
    reasons: List[str]

class PlatformLocalizationRequest(BaseModel):
    text: str
    target_language: str

class PlatformLocalizationResponse(BaseModel):
    translated_text: str

class PlatformEmbeddingRequest(BaseModel):
    text: str

class PlatformEmbeddingResponse(BaseModel):
    embedding: List[float]

class PlatformAudioBriefRequest(BaseModel):
    text: str
    language_code: str = "en-US"
    voice_name: str = "en-US-Neural2-C"

class PlatformAudioBriefResponse(BaseModel):
    audio_content: str # Base64 encoded audio content

from model_client import get_azure_openai_client, load_config
from model_models import PlatformInvocationRequest, StreamingPlatformInvocationResponse
from typing import Generator, Dict, Any
from openai import AzureOpenAI

def stream_platform_generation(request: PlatformInvocationRequest, config: Dict[str, Any] | None = None) -> Generator[StreamingPlatformInvocationResponse, None, None]:
    """Streams output from an Azure OpenAI managed model while preserving provider response objects."""
    config = config or load_config()
    client: AzureOpenAI = get_azure_openai_client(config)
    deployment_name = config.get('AZURE_OPENAI_DEPLOYMENT_NAME')

    if not deployment_name:
        raise ValueError("Azure OpenAI deployment name not specified in config or environment variables.")

    stream = client.chat.completions.create(
        model=deployment_name,
        messages=[
            {"role": "user", "content": request.text}
        ],
        temperature=request.temperature,
        max_tokens=request.max_tokens,
        stream=True
    )

    for chunk in stream:
        if chunk.choices and chunk.choices[0].delta.content:
            yield StreamingPlatformInvocationResponse(
                chunk=chunk.choices[0].delta.content,
                metadata={'id': chunk.id, 'model': chunk.model} # Example metadata
            )
